-- GameMatch 3.1 safe catalog/bootstrap migration.
-- Does not DROP, TRUNCATE, or delete users, wishlists, ratings, games, or offers.
-- It adds the 50 cross-platform baseline titles already shipped with GameMatch.
-- Steam sync then enriches/updates Steam-linked rows and live pricing.


CREATE TABLE IF NOT EXISTS gamematch_catalog_bootstrap_31 (title VARCHAR(150) NOT NULL, slug VARCHAR(170) NOT NULL, developer VARCHAR(150), publisher VARCHAR(150), release_date DATE, platforms VARCHAR(255) NOT NULL, genres VARCHAR(255) NOT NULL, game_mode VARCHAR(100) NOT NULL, age_rating VARCHAR(20) DEFAULT 'T', price DECIMAL(10,2) NOT NULL DEFAULT 0, description TEXT NOT NULL, cover_image VARCHAR(500) NOT NULL, trailer_url VARCHAR(500), steam_app_id INT NULL, store_rating DECIMAL(4,1) NULL, rating_count BIGINT DEFAULT 0, rating_source VARCHAR(50), featured TINYINT(1) DEFAULT 0);

DELETE FROM gamematch_catalog_bootstrap_31;




















































UPDATE games g
JOIN gamematch_catalog_bootstrap_31 s
  ON (s.steam_app_id IS NOT NULL AND g.steam_app_id = s.steam_app_id)
  OR LOWER(g.title) = LOWER(s.title)
SET
  g.name = s.title,
  g.title = s.title,
  g.slug = s.slug,
  g.developer = COALESCE(s.developer, g.developer),
  g.publisher = COALESCE(s.publisher, g.publisher),
  g.release_date = COALESCE(s.release_date, g.release_date),
  g.genre = s.genres,
  g.platform = s.platforms,
  g.mode = s.game_mode,
  g.platforms = s.platforms,
  g.genres = s.genres,
  g.game_mode = s.game_mode,
  g.age_rating = s.age_rating,
  g.description = s.description,
  g.image_url = s.cover_image,
  g.cover_image = s.cover_image,
  g.trailer_url = s.trailer_url,
  g.steam_app_id = COALESCE(s.steam_app_id, g.steam_app_id),
  g.source = CASE WHEN s.steam_app_id IS NULL THEN 'seed' ELSE g.source END,
  g.external_id = COALESCE(s.steam_app_id, g.external_id),
  g.store_rating = COALESCE(g.store_rating, s.store_rating),
  g.rating_count = CASE WHEN COALESCE(g.rating_count,0)=0 THEN s.rating_count ELSE g.rating_count END,
  g.rating_source = COALESCE(g.rating_source, s.rating_source),
  g.featured = s.featured;



 description,image_url,cover_image,trailer_url,steam_app_id,source,external_id,
 store_rating,rating_count,rating_source,featured)
SELECT
 s.title,s.title,s.slug,s.developer,s.publisher,s.release_date,s.genres,s.platforms,s.game_mode,s.age_rating,s.price,
 s.description,s.cover_image,s.cover_image,s.trailer_url,s.steam_app_id,'seed',
 COALESCE(CAST(s.steam_app_id AS CHAR),s.slug),
 s.store_rating,s.rating_count,s.rating_source,s.featured
FROM gamematch_catalog_bootstrap_31 s
WHERE NOT EXISTS (
    SELECT 1 FROM games g
    WHERE LOWER(g.title)=LOWER(s.title)
       OR (s.steam_app_id IS NOT NULL AND g.steam_app_id=s.steam_app_id)
);


DROP TABLE gamematch_catalog_bootstrap_31;